import Foundation

/// ffmpeg-made one-frame ProRes MXF files (7737 bytes each, orange 64×64 LT, orange 64×48 LT, orange 64×64 HQ); first picture frame at offset 6164. No footage or third-party assets.
enum MXFFixtures {
    static let frameOffset = 6164
    static let orange64By64ltLength = 236
    static let orange64By64lt: String = ""
    static let orange64By48ltLength = 218
    static let orange64By48lt: String = ""
    static let orange64By64hqLength = 240
    static let orange64By64hq: String = ""
    static let orange64By644444Length = 248
    static let orange64By644444: String = ""
    static func data(_ base64: String) -> Data { Data(base64Encoded: base64)! }
    static func frame(_ base64: String, length: Int) -> Data { data(base64).subdata(in: frameOffset ..< frameOffset + length) }
    static func write(_ base64: String, name: String, in root: URL) throws -> URL {
        let url = root.appendingPathComponent(name)
        try data(base64).write(to: url)
        return url
    }
}
